interface ATMState {
    void insertCard(ATM atm, Card card);
    void enterPin(ATM atm, char[] pin);
    void withdraw(ATM atm, Money amount);
}

class ATM {
    private ATMState state = new IdleState();
    private final BankGateway bank;
    private final CashDispenser dispenser;

    ATM(BankGateway bank, CashDispenser dispenser) {
        this.bank = bank;
        this.dispenser = dispenser;
    }

    void transitionTo(ATMState next) { state = next; }
    void insertCard(Card card) { state.insertCard(this, card); }
    void withdraw(Money amount) { state.withdraw(this, amount); }
    BankGateway bank() { return bank; }
    CashDispenser dispenser() { return dispenser; }
}

class IdleState implements ATMState {
    public void insertCard(ATM atm, Card card) {
        atm.transitionTo(new CardInsertedState(card));
    }
    public void enterPin(ATM atm, char[] pin) { throw new IllegalStateException("insert card first"); }
    public void withdraw(ATM atm, Money amount) { throw new IllegalStateException("authenticate first"); }
}
```
*Application configuration creates one aggregate for each physical machine; the class does not hide a global Singleton.*

